  isl_pureA sp P IN E lo shi c p0 bs h -> mem_inv bsegs m ->
  isl_side m P E p0 (Z.of_nat (length bs)) lo shi ->
  evt bsegs (isl_segA_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P IN E lo shi c pad7 pad2 p0 bs h g m)
